"""Static PNG figures for reports and the paper (generated by scripts/run_analysis.py)."""

from __future__ import annotations

from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import pandas as pd  # noqa: E402

from screening import config  # noqa: E402

# Colour-blind-safe (Okabe–Ito) colours, one per feature set.
SET_COLORS = {"A": "#0072B2", "B": "#E69F00", "C": "#009E73"}
MODEL_STYLES = {"logreg": ":", "rf": "--", "hgb": "-"}


def _finish(fig, path: Path) -> None:
    fig.tight_layout()
    fig.savefig(path, dpi=200)
    plt.close(fig)


def roc_figure(roc: pd.DataFrame, results: pd.DataFrame, path: Path) -> None:
    fig, ax = plt.subplots(figsize=(6.5, 5.5))
    for (fs, mdl), g in roc.groupby(["feature_set", "model"]):
        auc = results.query("feature_set == @fs and model == @mdl")["test_roc_auc"].iloc[0]
        ax.plot(g["fpr"], g["tpr"], MODEL_STYLES[mdl], color=SET_COLORS[fs], lw=1.6,
                label=f"Set {fs} · {config.MODEL_LABELS[mdl]} (AUC {auc:.3f})")
    ax.plot([0, 1], [0, 1], color="grey", lw=0.8, label="No discrimination")
    ax.set(xlabel="False-positive rate (1 − specificity)", ylabel="True-positive rate (recall)",
           title="ROC curves on the held-out test set")
    ax.legend(fontsize=7, loc="lower right")
    _finish(fig, path)


def pr_figure(pr: pd.DataFrame, results: pd.DataFrame, prevalence: float, path: Path) -> None:
    fig, ax = plt.subplots(figsize=(6.5, 5.5))
    for (fs, mdl), g in pr.groupby(["feature_set", "model"]):
        ap = results.query("feature_set == @fs and model == @mdl")["test_average_precision"].iloc[0]
        ax.plot(g["recall"], g["precision"], MODEL_STYLES[mdl], color=SET_COLORS[fs], lw=1.6,
                label=f"Set {fs} · {config.MODEL_LABELS[mdl]} (AP {ap:.3f})")
    ax.axhline(prevalence, color="grey", lw=0.8, label=f"Prevalence ({prevalence:.3f})")
    ax.set(xlabel="Recall", ylabel="Precision", ylim=(0, 1),
           title="Precision–recall curves on the held-out test set")
    ax.legend(fontsize=7, loc="upper right")
    _finish(fig, path)


def burden_figure(sweep: pd.DataFrame, path: Path) -> None:
    fig, ax = plt.subplots(figsize=(7, 4.5))
    ax.plot(sweep["k"], sweep["valid_roc_auc"], "o-", color=SET_COLORS["C"], label="Validation ROC-AUC")
    ax.plot(sweep["k"], sweep["valid_specificity"], "s--", color=SET_COLORS["B"],
            label="Validation specificity at ≥75% recall")
    ax.axhline(config.SET_C_MIN_VAL_AUC, color="grey", lw=0.8, ls=":",
               label=f"ROC-AUC rule ({config.SET_C_MIN_VAL_AUC})")
    sel = sweep[sweep["selected"]]
    if len(sel):
        ax.axvline(sel["k"].iloc[0], color="black", lw=0.8, ls="-.", label=f"Selected k = {sel['k'].iloc[0]}")
    ax.set(xlabel="Number of Set B questions kept (forward-ranked on training data)",
           ylabel="Metric value (validation set)", title="Question burden vs. screening performance",
           xticks=sweep["k"])
    ax.legend(fontsize=8, loc="lower right")
    _finish(fig, path)


def bmi_figure(df: pd.DataFrame, path: Path) -> None:
    fig, ax = plt.subplots(figsize=(7, 4.2))
    bins = range(10, 100, 2)
    for val, lbl, col in [(0, "Negative (class 0)", "#56B4E9"), (1, "Positive (class 1 or 2)", "#D55E00")]:
        ax.hist(df.loc[df[config.TARGET] == val, "BMI"], bins=bins, alpha=0.6, density=True,
                label=lbl, color=col)
    ax.set(xlabel="BMI (kg/m², as recorded in survey)", ylabel="Density (share of group per kg/m²)",
           title=f"BMI distribution by study target (all {len(df):,} records)")
    ax.legend()
    _finish(fig, path)
